let saved={},savedTheme='light';try{saved=JSON.parse(localStorage.getItem('retailscope-backlog')||'{}');savedTheme=localStorage.getItem('retailscope-theme')||'light';}catch{}
let state={page:nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'overview',busy:true,progress:'Menyiapkan data demo…',source:'Demo retail Indonesia',demo:true,meta:null,result:null,mapping:{},options:{dedupe:true,invoiceCancellation:false,dateOrder:'dmy',numberFormat:'plain'},filters:{start:'',end:'',region:''},currency:'IDR',k:'auto',metric:'revenue',search:'',clusterFilter:'all',churnFilter:'all',customerSort:'monetary-desc',customerPage:0,backlog:saved,error:'',dirty:false,menu:false,theme:savedTheme};
let applied=null;
const worker=new Worker('./worker.js');let sequence=0;const pending=new Map();
worker.onmessage=({data})=>{if(data.progress){state.progress=data.progress;const p=$('#progress');if(p)p.textContent=data.progress;return;}const p=pending.get(data.id);if(!p)return;pending.delete(data.id);data.error?p.reject(Error(data.error)):p.resolve(data.result);};
worker.onerror=()=>{for(const p of pending.values())p.reject(Error('Proses analisis terhenti. Muat ulang dan gunakan file lebih kecil.'));pending.clear();};
const call=(type,data={})=>new Promise((resolve,reject)=>{const id=++sequence;pending.set(id,{resolve,reject});worker.postMessage({type,id,...data});});
function money(v,compact=false){const currency=applied?.currency||state.currency;if(compact){const a=Math.abs(v);return (currency==='IDR'?'Rp':'£')+' '+decimal(v/(a>=1e9?1e9:a>=1e6?1e6:a>=1e3?1e3:1))+(a>=1e9?' M':a>=1e6?' jt':a>=1e3?' rb':'');}return new Intl.NumberFormat('id-ID',{style:'currency',currency,maximumFractionDigits:currency==='IDR'?0:2}).format(v||0);}
function date(s){if(!s)return '—';return new Date(s+'T00:00:00Z').toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});}
const button=(label,action,type='',ic='')=>`<button class="button ${type}" data-action="${action}" ${state.busy?'disabled':''}>${ic?icon(ic):''}${label}</button>`;
const head=(title,sub,extra='')=>`<div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${extra}</div>`;
const empty=msg=>`<div class="empty">${icon('info')}<p>${escape(msg)}</p></div>`;
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),5000);}
function shell(){const done=Object.values(state.backlog).filter(s=>s==='done').length;
 const currentNav=nav.find(n=>n[0]===state.page)||nav[0];
 return `<a class="skip-link" href="#main">Lewati ke konten</a><div class="shell ${state.menu?'menu-open':''}"><button class="mobile-overlay" data-action="menu" aria-label="Tutup navigasi"></button><aside class="sidebar"><div class="sidebar-top"><div class="brand-container"><a class="brand" href="#overview"><span class="brand-mark">${icon('chart')}</span><div class="brand-text"><span class="brand-name">RetailScope</span><span class="brand-badge">ENTERPRISE LAB</span></div></a></div><div class="workspace-card"><div class="workspace-head"><span class="status-pulse-dot"></span><strong>Retail Indonesia</strong></div><div class="workspace-sub">Riset Big Data · In-Memory Engine</div></div></div><nav class="sidebar-nav" aria-label="Navigasi utama">${navGroups.map(grp=>`<div class="nav-group"><div class="nav-group-title">${grp}</div><div class="nav-group-items">${nav.filter(n=>n[3]===grp).map(([id,label,ic])=>`<a class="nav-item ${state.page===id?'active':''}" href="#${id}" ${state.page===id?'aria-current="page"':''}><span class="nav-icon-wrap">${icon(ic)}</span><span class="nav-label-text">${label}</span>${id==='backlog'?'<span class="nav-count">25</span>':''}</a>`).join('')}</div></div>`).join('')}</nav><div class="sidebar-bottom"><div class="mini-project"><div class="mini-project-head"><strong>Progres Riset Backlog</strong><span class="badge-percent">${n(done/25*100)}%</span></div><div class="progress-track"><span style="width:${done/25*100}%"></span></div><small>${done} dari 25 sasaran penelitian selesai</small></div><div class="profile"><div class="avatar-ring"><div class="avatar">BD</div></div><div class="profile-info"><strong>Tim Peneliti Big Data</strong><small>Retail Intelligence 2026</small></div></div></div></aside><div class="topbar-wrap"><header class="topbar"><div class="topbar-left"><button class="menu-button" data-action="menu" aria-label="Buka navigasi">${icon('menu')}</button><div class="breadcrumbs"><span class="bc-root">Workspace</span><span class="bc-sep">${icon('chevron')}</span><span class="bc-group">${currentNav[3]}</span><span class="bc-sep">${icon('chevron')}</span><strong class="bc-current">${currentNav[1]}</strong></div></div><div class="topbar-right"><div class="engine-badge"><span class="status-pulse-dot inline"></span><span class="engine-text">${state.result?n(state.result.summary.rows)+' baris aktif':'Siap dianalisis'}</span></div><span class="chip ${state.demo?'amber':'blue'} font-mono">${state.demo?'DATA DEMO':'FILE PENGGUNA'}</span><div class="topbar-actions"><button class="button small subtle" data-action="toggle-theme" title="Ubah tema tampilan (Terang / Gelap)">${icon(state.theme==='dark'?'sun':'moon')}<span>${state.theme==='dark'?'Terang':'Gelap'}</span></button><button class="button small subtle" data-action="demo" title="Muat dataset demo">${icon('refresh')}<span>Data demo</span></button><a class="button small primary" href="#dataset">${icon('upload')}<span>Kelola dataset</span></a></div></div></header></div><main class="content" id="main">${content()}</main></div>`;
}
function title(title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow"><span class="eyebrow-dot"></span>RETAIL INTELLIGENCE PLATFORM / INDONESIA</div><h1>${title}</h1><p>${description}</p></div><div class="button-group">${actions}</div></div>`;}
function banner(){return `<div class="banner"><div class="banner-icon">${icon('info')}</div><div class="banner-content"><span>${state.demo?'<strong>Mode Demo Sintetis.</strong> Angka di halaman ini dihitung dari data transaksi retail Indonesia Jan–Nov 2025.':'<strong>Dataset Aktif Sesi Ini.</strong> '+escape(state.source)+' · Diproses lokal di browser (Web Worker terisolasi), data Anda aman dan tidak disimpan ke server.'}</span></div><button class="banner-action" data-action="go-dataset">${state.demo?'Ganti ke Dataset Sendiri':'Kelola Dataset'} ${icon('arrow')}</button></div>`;}
function content(){
 if(state.busy)return `${title('Menyiapkan analisis','Memproses transaksi di perangkat ini.')}<div class="loading"><span class="spinner"></span><p id="progress" role="status">${escape(state.progress)}</p></div>`;
 const errors=state.error?`<div class="notice error" role="alert">${escape(state.error)}</div>`:'';
 const body={overview:overview,dataset:dataset,cleaning:cleaning,trends:trends,segments:segments,backlog:backlogView,executive:executive,method:method,architecture:architecture}[state.page]();
 return errors+body+`<footer class="footer"><span><strong>RetailScope</strong> · Laboratorium analitik retail Indonesia</span><span>RFM + K-Means · ${state.result?n(state.result.summary.rows)+' baris dalam filter':'Dataset belum dianalisis'} · MVP browser</span></footer>`;
}
function render(){document.title=nav.find(n=>n[0]===state.page)?.[1]+' · RetailScope';document.documentElement.dataset.theme=state.theme;$('#app').innerHTML=shell();}
function noResult(){if(state.meta){return `<div class="notice"><strong>Dataset aktif: ${escape(state.source)} (${n(state.meta.count)} baris).</strong><br>File sudah berhasil diunggah, namun analisis belum dijalankan. Klik tombol di bawah untuk langsung memproses dan melihat hasilnya.</div><div class="button-group" style="margin-top:14px"><button class="button primary" data-action="run-analysis">${icon('spark')} Jalankan analisis sekarang</button><a href="#dataset" class="button">Atur pemetaan kolom ${icon('arrow')}</a></div>`;}return `<div class="notice">Dataset siap dipetakan. Lengkapi pemetaan kolom pada halaman Dataset dan klik <strong>Jalankan analisis</strong>.</div><a href="#dataset" class="button primary">Ke halaman Dataset ${icon('arrow')}</a>`;}
function filters(){const r=state.result,cities=r.availableCities||[];return `<form class="filters" id="filters-form"><span class="filter-label">${icon('filter')} Cakupan analisis</span><label>Dari tanggal<input type="date" name="start" value="${escape(state.filters.start)}" aria-label="Dari tanggal"></label><label>Sampai tanggal<input type="date" name="end" value="${escape(state.filters.end)}" aria-label="Sampai tanggal"></label><label>Wilayah<select name="region" aria-label="Wilayah"><option value="">Semua wilayah</option>${r.availableRegions.map(x=>`<option value="${escape(x)}" ${state.filters.region===x?'selected':''}>${escape(x)}</option>`).join('')}</select></label>${cities.length?`<label>Kota<select name="city" aria-label="Kota"><option value="">Semua kota</option>${cities.slice(0,100).map(x=>`<option value="${escape(x)}" ${state.filters.city===x?'selected':''}>${escape(x)}</option>`).join('')}</select></label>`:''}<button class="button primary" type="submit">Terapkan ${icon('arrow')}</button><button class="button" type="button" data-action="reset-filters">Reset</button></form>`;}
function stats(){const s=state.result.summary;return `<div class="stats">${[
 ['Total Nilai Penjualan',money(s.revenue,true),'money',(applied?.options.valueMode==='order'?'Total pembayaran pesanan yang lolos cleaning':'Pembelian positif · sebelum diskon/ongkir'),'Omzet Bersih'],
 ['Total Pesanan Unik',n(s.orders),'bag','ID pesanan unik dalam periode terpilih','Volume Transaksi'],
 ['Pelanggan Teridentifikasi',n(s.customers),'users','ID pembeli unik dasar RFM & K-Means','Populasi Pembeli'],
 ['Rata-rata Nilai Pesanan',money(s.aov,true),'chart','Nilai penjualan ÷ pesanan unik (AOV)','Average Basket Size']
 ].map(([label,value,ic,note,tag])=>`<article class="stat"><div class="stat-head"><span class="stat-tag">${tag}</span><span class="stat-icon">${icon(ic)}</span></div><div class="stat-value" title="${escape(value)}">${value}</div><div class="stat-label">${label}</div><div class="stat-foot">${note}</div></article>`).join('')}</div>`;}
function chart(items,key,label,format=(v)=>n(v),id='line'){
 if(!items.length)return empty('Tidak ada data pada filter ini.');
 const w=690,h=245,left=61,right=15,top=18,bottom=36,plotW=w-left-right,plotH=h-top-bottom,max=Math.max(...items.map(x=>x[key]))||1;
 const x=i=>left+(items.length===1?plotW/2:i*plotW/(items.length-1)),y=v=>top+plotH-v/max*plotH;
 const points=items.map((a,i)=>`${x(i)},${y(a[key])}`).join(' ');
 const tickEvery=Math.max(1,Math.ceil(items.length/9));
 return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${escape(label)}"><title>${escape(label)}</title><defs><linearGradient id="fill-${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#10b981" stop-opacity=".26"/><stop offset="100%" stop-color="#10b981" stop-opacity=".01"/></linearGradient></defs>${[0,.25,.5,.75,1].map(f=>`<line class="gridline" x1="${left}" y1="${y(max*f)}" x2="${w-right}" y2="${y(max*f)}"/><text x="${left-11}" y="${y(max*f)+4}" text-anchor="end">${escape(format(max*f))}</text>`).join('')}<polygon fill="url(#fill-${id})" points="${x(0)},${top+plotH} ${points} ${x(items.length-1)},${top+plotH}"/><polyline points="${points}" fill="none" stroke="var(--primary)" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>${items.map((a,i)=>`<circle cx="${x(i)}" cy="${y(a[key])}" r="3.8" fill="var(--surface)" stroke="var(--primary)" stroke-width="2.2"><title>${escape(a.month||'k = '+a.k)}: ${escape(format(a[key]))}</title></circle>${i%tickEvery===0||i===items.length-1?`<text x="${x(i)}" y="${h-11}" text-anchor="middle">${escape(a.month?monthLabel(a.month):'k = '+a.k)}</text>`:''}`).join('')}</svg>`;
}
function monthLabel(s){return new Date(s+'-01T00:00:00Z').toLocaleDateString('id-ID',{month:'short',year:'2-digit',timeZone:'UTC'});}
function trendPanel(){const r=state.result,metric=state.metric,peak=[...r.monthly].sort((a,b)=>b[metric]-a[metric])[0];
 return `<section class="panel">${head('Tren penjualan',r.summary.start?date(r.summary.start)+' — '+date(r.summary.end):'Tidak ada transaksi',`<div class="chart-tabs" aria-label="Metrik grafik"><button data-metric="revenue" class="${metric==='revenue'?'active':''}">Penjualan</button><button data-metric="orders" class="${metric==='orders'?'active':''}">Pesanan</button></div>`)}<div class="panel-body"><div class="chart-summary">${peak?`Puncak ${metric==='revenue'?'penjualan':'pesanan'}: <b>${escape(monthLabel(peak.month))}</b> · ${metric==='revenue'?money(peak.revenue,true):n(peak.orders)+' pesanan'}`:'Belum ada data.'}</div>${chart(r.monthly,metric,'Grafik '+(metric==='revenue'?'nilai penjualan':'pesanan unik')+' per bulan',metric==='revenue'?v=>money(v,true):n)}<div class="legend"><span><i></i>${metric==='revenue'?'Nilai pembelian positif':'Pesanan unik per bulan'}</span></div></div><div class="panel-note">Bulan pertama/terakhir dapat parsial. ${applied?.options.valueMode==='order'?'Nilai mengikuti kolom total pembayaran sumber; komponen diskon/ongkir mengikuti definisi sumber.':'Nilai penjualan tidak dikurangi retur, diskon, atau ongkir.'}</div></section>`;
}
function donut(){const seg=state.result.segmentation,total=seg.customers.length;let offset=0;
 if(!seg.k)return empty(seg.message||'Belum ada segmentasi.');
 const circumference=2*Math.PI*63;
 return `<div class="segment-overview"><div class="donut-wrap"><svg class="donut" viewBox="0 0 156 156" role="img" aria-label="Distribusi ${seg.k} cluster pelanggan"><title>${seg.clusters.map(c=>`${c.name}: ${c.count} pelanggan`).join('; ')}</title><circle cx="78" cy="78" r="63" fill="none" stroke="var(--bg-subtle)" stroke-width="18"/>${seg.clusters.map((c,i)=>{const length=c.count/total*circumference,s=`<circle cx="78" cy="78" r="63" fill="none" stroke="${palette[i]}" stroke-width="18" stroke-dasharray="${Math.max(0,length-2)} ${circumference}" stroke-dashoffset="${-offset}"/>`;offset+=length;return s;}).join('')}</svg><div class="donut-center"><b>${n(total)}</b><span>pelanggan</span></div></div><div class="cluster-legend">${seg.clusters.map((c,i)=>`<div><i style="background:${palette[i]}"></i>${c.name}<b>${decimal(c.count/total*100)}%</b></div>`).join('')}</div></div>`;
}
function segmentPanel(){const s=state.result.segmentation,top=s.clusters[0];return `<section class="panel">${head('Segmen pelanggan','Pengelompokan perilaku pembelian',`<a class="button small subtle" href="#segments">Detail ${icon('arrow')}</a>`)}<div class="panel-body">${donut()}${top?`<div class="insight">${icon('spark')}<span><strong>${top.name}</strong> memiliki rerata pembelian tertinggi, ${money(top.monetary,true)} per pelanggan. Tinjau profil RFM sebelum menentukan strategi.</span></div>`:''}</div><div class="panel-note">${s.k?`K = ${s.k} · Silhouette ${s.silhouette===null?'tidak terdefinisi':decimal(s.silhouette)} · log1p + standardisasi`:'ID pelanggan diperlukan untuk analisis RFM.'}</div></section>`;}
function productsPanel(limit=5){if((applied?.options||state.options).valueMode==='order'){const cats=state.result.categories||[];if(!cats.length)return `<section class="panel">${head('Analisis produk tidak tersedia','Dataset berisi ringkasan pesanan')}${empty('Tidak ada SKU individual dan kategori belum dipetakan.')}</section>`;return `<section class="panel">${head('Kategori produk terpopuler','Diurutkan berdasarkan frekuensi pesanan',`<span class="chip">TOP ${limit} KATEGORI</span>`)}<div class="table-wrap"><table><thead><tr><th>Kategori Produk</th><th class="numeric">Pesanan</th><th class="numeric">Kuantitas</th></tr></thead><tbody>${cats.slice(0,limit).map((c,i)=>`<tr><td><div class="product-cell"><span class="product-avatar">${String(i+1).padStart(2,'0')}</span><div><strong>${escape(c.name)}</strong><small>Kategori belanja</small></div></div></td><td class="numeric"><strong>${n(c.orders)}</strong> pesanan</td><td class="numeric">${n(c.quantity)} unit</td></tr>`).join('')}</tbody></table></div><div class="panel-note">Agregasi dihitung dari kemunculan kategori pada transaksi yang lolos audit cleaning.</div></section>`;}return `<section class="panel">${head('Produk terlaris','Diurutkan berdasarkan jumlah unit terjual',`<span class="chip">TOP ${limit}</span>`)}<div class="table-wrap"><table><thead><tr><th>Produk</th><th class="numeric">Unit terjual</th><th class="numeric">Nilai penjualan</th></tr></thead><tbody>${state.result.products.slice(0,limit).map((p,i)=>`<tr><td><div class="product-cell"><span class="product-avatar">${String(i+1).padStart(2,'0')}</span><div><strong>${escape(p.name)}</strong><small>${escape(p.id)}</small></div></div></td><td class="numeric">${n(p.quantity)}</td><td class="numeric"><strong>${money(p.revenue,true)}</strong></td></tr>`).join('')||'<tr><td colspan="3">Tidak ada produk pada filter ini.</td></tr>'}</tbody></table></div><div class="panel-note">ID produk menjadi kunci agregasi; nama diambil dari baris pertama.</div></section>`;}
function regionsPanel(){const regions=state.result.regions.slice(0,6),all=state.result.summary.orders,max=regions[0]?.orders||1;return `<section class="panel">${head('Pesanan menurut wilayah','ID pesanan unik di setiap provinsi / wilayah',`<span class="chip">${state.result.regions.length} WILAYAH</span>`)}<div class="panel-body bars">${regions.map(r=>`<div class="bar-item"><div class="bar-head"><span>${escape(r.name)}</span><b>${n(r.orders)} <small>pesanan</small></b></div><div class="progress-track"><span style="width:${r.orders/max*100}%"></span></div></div>`).join('')||empty('Tidak ada wilayah pada filter ini.')}</div><div class="panel-note">${regions[0]?`${escape(regions[0].name)} memimpin dengan ${decimal(regions[0].orders/(all||1)*100)}% dari pesanan unik dalam filter.`:'Petakan kolom provinsi untuk melihat distribusi.'}</div></section>`;}
function overview(){return title('Ringkasan analisis','Gambaran penjualan dan perilaku pelanggan, dalam satu tempat.',button('Ekspor ringkasan','export-json','','download'))+banner()+(state.result?filters()+stats()+`<div class="grid-main">${trendPanel()}${segmentPanel()}</div><div class="grid-main">${productsPanel()}${regionsPanel()}</div>`:noResult());}
function dataset(){const m=state.meta;
 return title('Dataset & sumber data','Mulai dari data yang tepat. Periksa skema, lalu jalankan analisis.',button('Gunakan demo','demo','','refresh'))+banner()+`<div class="grid-halves"><section class="panel">${head('Masukkan dataset','CSV atau Excel dengan satu skema transaksi')}<div class="panel-body"><label class="upload-zone" id="dropzone" for="file"><span>${icon('upload')}</span><strong>Pilih file atau tarik ke sini</strong><p>CSV, XLSX, XLS · maksimum 120 MB<br>Excel: seluruh sheet terlihat digabung bila skemanya sama.</p><span class="button primary small">Pilih dataset</span></label><input type="file" id="file" accept=".csv,.xlsx,.xls" hidden><div class="checks"><small style="color:var(--muted);line-height:1.7">Dataset tersimpan otomatis di memori lokal browser (IndexedDB) sehingga tetap bertahan saat halaman di-refresh. Jangan unggah tabel ulasan, katalog produk, atau statistik penjualan agregat untuk RFM.</small></div><div class="button-group">${button('Unduh template CSV','template','small','download')}${button('Unduh data demo','download-demo','small subtle','download')}</div></div></section><section class="panel">${head('Dataset aktif','Ringkasan sebelum cleaning')}<div class="panel-body prose"><div class="metric-inline"><div>Baris mentah<b>${n(m?.count)}</b></div><div>Kolom<b>${n(m?.headers.length)}</b></div><div>Sumber<b style="font-size:13px">${state.demo?'Sintetis':'File pengguna'}</b></div></div><p><strong>${escape(state.source)}</strong></p><p>${m?.sheets?'Sheet: '+m.sheets.map(escape).join(', '):'Satu tabel. Periksa unit observasi sumber: baris item atau satu pesanan.'}</p><p>${state.options.valueMode==='order'?'Mode total pembayaran per pesanan terdeteksi. Nilai pembayaran dijumlahkan langsung. ID pelanggan diperlukan hanya untuk RFM.':'Mode baris produk: nilai transaksi dihitung dari kuantitas × harga satuan. Pilih mode total pembayaran pada pemetaan jika sumber berisi ringkasan pesanan.'}</p></div></section></div>${m?mappingPanel():''}${m?previewPanel():''}${sourcesPanel()}`;
}
const fields=[['amount','Total pembayaran per pesanan',false],['invoice','ID pesanan / invoice',true],['date','Tanggal transaksi',true],['customer','ID pelanggan',false],['product','ID produk',false],['description','Nama produk',false],['category','Kategori produk',false],['quantity','Kuantitas',true],['price','Harga satuan',true],['payment','Metode pembayaran',false],['shipping','Opsi pengiriman',false],['region','Provinsi / wilayah',false],['city','Kota',false],['status','Status pesanan',false]];
function mappingPanel(){const m=state.meta;const orderMode=state.options.valueMode==='order';const missing=(orderMode?[['invoice','ID pesanan'],['date','tanggal'],['quantity','kuantitas'],['amount','total pembayaran']]:[['invoice','ID pesanan'],['date','tanggal'],['quantity','kuantitas'],['price','harga satuan']]).filter(([key])=>!state.mapping[key]).map(([,label])=>label);return `<section class="panel section-gap"><form id="mapping-form" novalidate>${head('Pemetaan kolom & aturan analisis','Kolom terdeteksi otomatis. Periksa kembali sebelum memproses file.',`<button class="button primary small" type="submit">${icon('spark')} Jalankan analisis</button>`)}<div class="panel-body"><div class="notice"><strong>Langkah 2 dari 3: periksa kolom, lalu jalankan analisis.</strong> File sudah berhasil diunggah. ${orderMode?'Mode total pembayaran: satu baris per pesanan. Nilai pembayaran digunakan langsung, tanpa dikalikan kuantitas.':'Mode item: nilai penjualan = kuantitas × harga satuan.'}</div><div class="field"><label for="value-mode">Bentuk nilai transaksi</label><select id="value-mode" name="valueMode"><option value="item" ${!orderMode?'selected':''}>Baris produk · kuantitas × harga satuan</option><option value="order" ${orderMode?'selected':''}>Satu baris pesanan · total pembayaran langsung</option></select></div>${!state.mapping.customer?'<div class="notice warning"><strong>Tren penjualan tersedia setelah pemetaan lengkap.</strong> Segmentasi RFM tidak tersedia karena ID pelanggan belum dipetakan. Jangan gunakan nomor pesanan atau kota sebagai ID pelanggan.</div>':''}${missing.length?`<div class="notice warning"><strong>Kolom wajib belum terdeteksi: ${missing.join(", ")}.</strong> Petakan kolom yang setara jika tersedia. Jika sumber tidak menyediakan nilai tersebut, dataset belum dapat dipakai untuk analisis lengkap. Jangan menambahkan harga rekaan atau menjadikan nomor baris sebagai ID pesanan tanpa dokumentasi.</div>`:""}<div class="fields">${fields.filter(([key])=>orderMode?!['price','product','description'].includes(key):key!=='amount').map(([key,label,required])=>{const req=orderMode?['invoice','date','quantity','amount'].includes(key):required;return `<div class="field"><label for="map-${key}">${label} ${req?'<b>*</b>':''}</label><select id="map-${key}" name="map-${key}" ${req?'required':''}><option value="">${key==='customer'?'Tidak tersedia (RFM nonaktif)':'Tidak dipetakan'}</option>${m.headers.map(h=>`<option value="${escape(h)}" ${state.mapping[key]===h?'selected':''}>${escape(h)}</option>`).join('')}</select>${key==='product'?'<small>Minimal salah satu: ID produk atau nama produk.</small>':key==='status'?'<small>Kosong: semua transaksi diasumsikan final. Jika dipetakan, hanya status sukses yang dihitung.</small>':''}</div>`;}).join('')}<div class="field"><label for="currency">Mata uang dataset</label><select id="currency" name="currency"><option value="IDR" ${state.currency==='IDR'?'selected':''}>IDR · Rupiah</option><option value="GBP" ${state.currency==='GBP'?'selected':''}>GBP · Pound sterling</option></select><small>Label mata uang, tanpa konversi kurs. Jangan campur mata uang.</small></div><div class="field"><label for="date-order">Urutan tanggal non-ISO</label><select id="date-order" name="dateOrder"><option value="dmy" ${state.options.dateOrder==='dmy'?'selected':''}>DD/MM/YYYY · Indonesia</option><option value="mdy" ${state.options.dateOrder==='mdy'?'selected':''}>MM/DD/YYYY · Amerika</option></select><small>YYYY-MM-DD dan tanggal Excel tetap didukung.</small></div><div class="field"><label for="number-format">Format angka</label><select id="number-format" name="numberFormat"><option value="plain" ${state.options.numberFormat==='plain'?'selected':''}>12345.67 · angka standar</option><option value="id" ${state.options.numberFormat==='id'?'selected':''}>12.345,67 · format Indonesia</option></select><small>Angka bertipe numerik di Excel tidak diubah.</small></div></div><div class="checks"><label class="check"><input type="checkbox" name="dedupe" ${state.options.dedupe?'checked':''}>Hapus duplikat identik pada seluruh kolom sumber. Nonaktifkan bila baris identik merupakan pembelian yang sah.</label><label class="check"><input type="checkbox" name="invoiceCancellation" ${state.options.invoiceCancellation?'checked':''}>Invoice berawalan C berarti pembatalan (khusus skema seperti Online Retail II).</label><label class="check"><input type="checkbox" name="proxyCustomer" ${state.options.proxyCustomer?'checked':''}><strong>Simulasi ID Pelanggan (Proxy RFM):</strong> Buat identitas pelanggan sementara untuk menguji segmentasi K-Means jika dataset tidak memiliki kolom ID pelanggan.</label></div><div class="notice">${icon('info')} Status sukses yang dikenali: completed, complete, selesai, delivered, success, successful, paid, terkirim, diterima, lunas. Status lain dikeluarkan sebagai belum final/tidak dikenal. Kuantitas negatif dianggap retur. ID pelanggan kosong hanya dikeluarkan dari RFM.</div><button class="button primary" type="submit">${icon('spark')} Jalankan analisis</button></div></form></section>`;}
function previewPanel(){const m=state.meta;return `<section class="panel section-gap">${head('Pratinjau data mentah','8 baris pertama · sebelum transformasi')}<div class="table-wrap"><table><thead><tr>${m.headers.map(h=>`<th>${escape(h)}</th>`).join('')}</tr></thead><tbody>${m.preview.map(r=>`<tr>${m.headers.map(h=>`<td>${escape(r[h])||'<span class="chip amber">kosong</span>'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
function sourcesPanel(){return `<section class="panel section-gap">${head('Sumber dataset transaksi Indonesia','Hanya sumber non-simulasi sebagai kandidat laporan. Kelayakan RFM perlu diperiksa terpisah.')}<div class="panel-body"><div class="source-card"><h3>Repeat Buyer E-commerce Dataset <span class="chip">SUMBER PENELITIAN</span></h3><p>Siska F Mauludiah · Mendeley Data · DOI 10.17632/hwvz4kv232.1 · CC BY 4.0. Menurut pembuat, dikumpulkan dari lingkungan e-commerce Indonesia dengan dukungan perusahaan transformasi digital.</p><p>File asli sudah diperiksa: 1.000 baris, 178 ID pelanggan, 10 kolom, Juni–Juli 2022. Memiliki Trx_Date, Cust_ID, AREA, Product_ID, Product_Name dan Amount, tetapi tidak menyediakan harga/nilai uang maupun ID pesanan yang terdokumentasi. Kolom No adalah nomor urut. Amount berisi bilangan kecil; makna satuannya perlu dikonfirmasi, jangan dianggap Rupiah. Belum cukup untuk Monetary RFM.</p><a href="https://data.mendeley.com/datasets/hwvz4kv232/1" target="_blank" rel="noopener noreferrer">Halaman sumber ↗</a> · <a href="https://data.mendeley.com/public-files/datasets/hwvz4kv232/files/32108096-1f78-4e1c-8d4c-b2b52aafd6d3/file_downloaded" target="_blank" rel="noopener noreferrer">Unduh CSV asli ↗</a></div><div class="source-card"><h3>Indonesia E-Commerce Sales & Shipping 2023–2025 <span class="chip blue">KAGGLE</span></h3><p>Pembuat menyebut transaksi penjualan/pengiriman Indonesia. Skema yang dipublikasikan tidak mencantumkan customer_id: cocok ditinjau untuk tren, belum untuk RFM pelanggan. Jangan menjadikan order_id atau kota sebagai ID pelanggan.</p><a href="https://www.kaggle.com/datasets/bakitacos/indonesia-e-commerce-sales-and-shipping-20232025" target="_blank" rel="noopener noreferrer">Buka di Kaggle ↗</a> · <a href="https://github.com/BakiTacos/Indonesia-Ecommerce-Sales-Shipping-Data-2023-2025" target="_blank" rel="noopener noreferrer">Dokumentasi pembuat ↗</a></div><div class="source-card"><h3>Retail sales dataset of a pharmacy in Indonesia</h3><p>Rendra Gustriansyah · Mendeley Data · CC BY 4.0. Pembuat menyatakan data berasal dari database apotek asli. File SQL memerlukan pengolahan dahulu. Konteks online tidak dinyatakan; KD_CUST dijelaskan sebagai nomor registrasi, bukan nomor rekam medis, sehingga identitas pelanggan berulang belum terjamin. Alternatif tren penjualan, bukan pengganti langsung topik online retail/RFM.</p><a href="https://data.mendeley.com/datasets/2ym7v78wtd/1" target="_blank" rel="noopener noreferrer">Sumber & unduh arsip ↗</a></div><div class="notice warning">Belum ada satu kandidat di atas yang terverifikasi memenuhi seluruh kebutuhan online retail Indonesia + RFM. Dataset simulasi tidak dipilih untuk laporan akhir. Gunakan ekspor transaksi asli dengan ID pelanggan stabil, ID pesanan, tanggal, produk, kuantitas, dan harga; minta izin pemilik data bila memakai data toko.</div></div></section>`;}
function cleaning(){if(!state.result)return title('Data cleaning','Audit aturan sebelum membaca hasil analisis.')+noResult();const c=state.result.cleaning;
 const steps=[['Data mentah','Jumlah seluruh baris dari file / demo.',c.raw],['Duplikat identik dihapus',applied.options.dedupe?'Kesamaan seluruh kolom sumber; diproses pertama.':'Penghapusan duplikat dinonaktifkan.',c.duplicates],['Pembatalan & retur dikeluarkan','Status batal/retur, kuantitas negatif'+(applied.options.invoiceCancellation?', atau invoice berawalan C.':'.'),c.cancelled],['Belum final / status tak dikenal','Jika kolom status dipetakan, hanya status sukses yang masuk.',c.pending],['Nilai wajib tidak valid',(applied.options.valueMode==='order'?'Invoice kosong, tanggal/kuantitas tidak valid, atau total pembayaran ≤ 0.':'Invoice/produk kosong, tanggal tidak valid, kuantitas ≤ 0 atau harga ≤ 0.'),c.invalid],['Baris valid untuk penjualan','Baris yang lolos semua aturan; sebelum filter periode/wilayah.',c.valid],['ID pelanggan kosong','Tetap dalam penjualan; dikecualikan dari perhitungan RFM.',c.missingCustomer],['Nama produk kosong','Diisi dengan kode produk yang tersedia.',c.missingDescription]];
 return title('Audit kualitas data','Lihat apa yang berubah, dan mengapa setiap baris dipertahankan atau dikeluarkan.',button('Ekspor data bersih','export-clean','','download'))+banner()+`<div class="grid-main"><section class="panel">${head('Jejak pembersihan data','Hitungan cleaning seluruh dataset; filter dashboard diterapkan sesudahnya.')} ${steps.map(([name,desc,count],i)=>`<div class="audit-row"><span class="audit-number">${String(i+1).padStart(2,'0')}</span><div><strong>${name}</strong><p>${escape(desc)}</p></div><span class="audit-count">${n(count)}</span></div>`).join('')}</section><div><section class="panel section-gap">${head('Kualitas hasil cleaning','Transparansi sebelum interpretasi')}<div class="panel-body"><div class="stat-value">${decimal(c.raw?c.valid/c.raw*100:0)}%</div><p style="color:var(--muted);font-size:12px;margin-bottom:15px">baris lolos aturan penjualan</p><div class="progress-track"><span style="width:${c.raw?c.valid/c.raw*100:0}%"></span></div><div class="formula">Mentah = duplikat + batal/retur<br>+ belum final + invalid + valid<br><br>${n(c.raw)} = ${n(c.duplicates)} + ${n(c.cancelled)}<br>+ ${n(c.pending)} + ${n(c.invalid)} + ${n(c.valid)}</div></div></section><section class="panel">${head('Keputusan analisis','Aturan yang digunakan untuk hasil aktif')}<div class="panel-body prose"><p>Monetary menggunakan nilai pembelian positif sebelum diskon dan ongkir. Retur dikeluarkan; nilai ini bukan pendapatan bersih.</p><p>Tanggal referensi RFM mengikuti tanggal transaksi maksimum dalam filter + 1 hari. Data kosong tidak diimputasi menjadi pelanggan baru.</p><p>Data ekstrem yang valid tetap dipertahankan. Transformasi log1p dan standardisasi diterapkan pada RFM sebelum clustering.</p><a class="button small" href="#dataset">Ubah aturan ${icon('arrow')}</a></div></section></div></div>`;
}
function paymentsPanel(){const pays=state.result.payments||[],all=state.result.summary.orders||1,max=pays[0]?.orders||1;if(!pays.length)return '';return `<section class="panel">${head('Metode pembayaran','Preferensi transaksi pembeli',`<span class="chip">${pays.length} METODE</span>`)}<div class="panel-body bars">${pays.slice(0,5).map(p=>`<div class="bar-item"><div class="bar-head"><span><strong>${escape(p.name)}</strong> (${decimal(p.orders/all*100)}%)</span><b>${n(p.orders)} <small>pesanan</small></b></div><div class="progress-track"><span style="width:${p.orders/max*100}%"></span></div></div>`).join('')}</div><div class="panel-note">${pays[0]?`${escape(pays[0].name)} memimpin dengan ${decimal(pays[0].orders/all*100)}% dari pesanan unik.`:'Data pembayaran.'}</div></section>`;}
function hourlyPanel(){const hours=state.result.hourly||[],max=Math.max(...hours.map(h=>h.orders))||1;const peak=hours.slice().sort((a,b)=>b.orders-a.orders)[0];if(!hours.some(h=>h.orders>0))return '';const w=690,h=130,barW=17,gap=(w-40-barW*24)/23;return `<section class="panel">${head('Pola jam sibuk transaksi (24 Jam)','Waktu pesanan dibuat sepanjang hari',`<span class="chip">${peak?`PUNCAK: ${peak.label}`:'24 JAM'}</span>`)}<div class="panel-body"><svg viewBox="0 0 ${w} ${h}" class="chart" role="img" aria-label="Grafik pesanan per jam"><title>Pola jam transaksi</title>${hours.map((h,i)=>{const barH=Math.max(3,(h.orders/max)*80);const x=20+i*(barW+gap);const y=100-barH;return `<rect x="${x}" y="${y}" width="${barW}" height="${barH}" rx="3.5" fill="${h.hour===peak?.hour?'#145337':'#6ee7b7'}"><title>${h.label}: ${n(h.orders)} pesanan</title></rect>${i%3===0?`<text x="${x+barW/2}" y="118" text-anchor="middle" font-size="9.5" fill="#5a7063">${h.hour}</text>`:''}`;}).join('')}</svg></div><div class="panel-note">Jam puncak aktivitas belanja tercatat pada <strong>${peak?.label}</strong> dengan <strong>${n(peak?.orders)} pesanan</strong>.</div></section>`;}
function basketPanel(){const ba=state.result.basketAnalysis;if(!ba||!ba.rules.length)return '';return `<section class="panel section-gap">${head('Market Basket Analysis (Asosiasi Keranjang Belanja)','Pola produk & kategori yang sering dibeli bersamaan (Aturan Asosiasi / Apriori Algorithm)',`<span class="chip green">${ba.rules.length} ATURAN ASOSIASI</span>`)}<div class="table-wrap"><table><thead><tr><th>Pasangan Belanja</th><th>Arah Asosiasi</th><th class="numeric">Support</th><th class="numeric">Confidence</th><th class="numeric">Lift</th><th>Rekomendasi Bundling & Cross-Selling</th></tr></thead><tbody>${ba.rules.map(r=>`<tr><td><strong>${escape(r.pair)}</strong></td><td><span class="chip blue">${escape(r.antecedent)} → ${escape(r.consequent)}</span></td><td class="numeric">${decimal(r.support*100)}%</td><td class="numeric"><strong>${decimal(r.confidence*100)}%</strong></td><td class="numeric"><span class="chip green">Lift ${decimal(r.lift)}×</span></td><td><small>${escape(r.strategy)}</small></td></tr>`).join('')}</tbody></table></div><div class="panel-note">Dihitung dari ${n(ba.multiBaskets)} transaksi multikategori (${ba.type==='order'?'keranjang pesanan unik':'riwayat pesanan pembeli'}). Nilai <strong>Lift &gt; 1.0</strong> membuktikan kecenderungan kuat untuk dibeli bersama.</div></section>`;}
function paretoPanel(){const p=state.result.pareto,s=state.result.summary;if(!p)return '';return `<section class="panel section-gap">${head('Konsentrasi Pareto 80/20 & Retensi Pembeli (Repeat Buyer)','Distribusi kontribusi omzet pelanggan, SKU produk, dan tingkat pembelian berulang',`<span class="chip green">REPEAT RATE ${decimal(p.repeatRatePct)}%</span>`)}<div class="panel-body"><div class="metric-inline"><div>Pembeli Berulang (&gt;1×)<b>${n(p.repeatCustomers)} <small style="font-size:12px;font-weight:500;color:var(--muted)">(${decimal(p.repeatRatePct)}%)</small></b></div><div>Pembeli Satu Kali (1×)<b>${n(p.oneTimeCustomers)}</b></div><div>Kontribusi Repeat Buyer<b>${decimal(p.repeatRevenueSharePct)}% omzet</b></div><div>Pareto 20% Pembeli Teratas<b>${decimal(p.top20CustomerSharePct)}% omzet</b></div><div>Pareto 20% Produk Teratas<b>${decimal(p.top20ProductSharePct)}% omzet</b></div></div><div class="bars"><div class="bar-item"><div class="bar-head"><span><strong>Kontribusi Omzet Pembeli Berulang</strong> (${n(p.repeatCustomers)} dari ${n(s.customers)} pelanggan)</span><b>${decimal(p.repeatRevenueSharePct)}%</b></div><div class="progress-track"><span style="width:${Math.min(100,p.repeatRevenueSharePct)}%"></span></div></div><div class="bar-item"><div class="bar-head"><span><strong>Konsentrasi Pareto 20% Pelanggan Teratas</strong> (${n(p.top20CustomerCount)} pelanggan menyumbang omzet utama)</span><b>${decimal(p.top20CustomerSharePct)}%</b></div><div class="progress-track"><span style="width:${Math.min(100,p.top20CustomerSharePct)}%"></span></div></div><div class="bar-item"><div class="bar-head"><span><strong>Konsentrasi Pareto 20% Produk Teratas</strong> (${n(p.top20ProductCount)} SKU menyumbang omzet utama)</span><b>${decimal(p.top20ProductSharePct)}%</b></div><div class="progress-track"><span style="width:${Math.min(100,p.top20ProductSharePct)}%"></span></div></div></div></div><div class="panel-note">Hukum Pareto 80/20 menguji seberapa terkonsentrasi omzet pada segelintir pelanggan/produk utama serta kekuatan retensi transaksi berulang.</div></section>`;}
function dayOfWeekPanel(){const days=state.result.dayOfWeek||[],max=Math.max(...days.map(d=>d.orders))||1,peak=days.slice().sort((a,b)=>b.orders-a.orders)[0];if(!days.some(d=>d.orders>0))return '';const w=690,h=150,barW=54,gap=(w-80-barW*7)/6;return `<section class="panel">${head('Pola Hari Belanja (Senin — Minggu)','Distribusi volume pesanan unik dan omzet menurut hari dalam seminggu',`<span class="chip">${peak?`PUNCAK: ${peak.name.toUpperCase()}`:'7 HARI'}</span>`)}<div class="panel-body"><svg viewBox="0 0 ${w} ${h}" class="chart" role="img" aria-label="Grafik pesanan per hari dalam seminggu"><title>Pola hari belanja</title>${days.map((d,i)=>{const barH=Math.max(4,(d.orders/max)*92),x=40+i*(barW+gap),y=112-barH,isPeak=d.day===peak?.day;return `<rect x="${x}" y="${y}" width="${barW}" height="${barH}" rx="6" fill="${isPeak?'var(--primary)':'#6ee7b7'}"><title>${d.name}: ${n(d.orders)} pesanan · ${money(d.revenue,true)}</title></rect><text x="${x+barW/2}" y="${y-6}" text-anchor="middle" font-size="10" font-weight="700" fill="var(--text-secondary)">${n(d.orders)}</text><text x="${x+barW/2}" y="132" text-anchor="middle" font-size="11" font-weight="${isPeak?'700':'500'}" fill="${isPeak?'var(--text)':'var(--muted)'}">${d.name.slice(0,3)}</text>`;}).join('')}</svg></div><div class="panel-note">Hari tersibuk adalah <strong>${escape(peak?.name)}</strong> dengan <strong>${n(peak?.orders)} pesanan unik</strong> (${money(peak?.revenue||0,true)}).</div></section>`;}
function citiesPanel(){const cities=(state.result.cities||[]).filter(c=>c.name&&c.name!=='Tidak diketahui'),all=state.result.summary.orders||1,max=cities[0]?.orders||1;if(!cities.length)return '';return `<section class="panel">${head('Top Kota & Kabupaten','Konsentrasi pesanan unik tingkat kota/kabupaten',`<span class="chip">${cities.length} KOTA</span>`)}<div class="panel-body bars">${cities.slice(0,6).map(c=>`<div class="bar-item"><div class="bar-head"><span><strong>${escape(c.name)}</strong> (${decimal(c.orders/all*100)}%)</span><b>${n(c.orders)} <small>pesanan · ${money(c.revenue,true)}</small></b></div><div class="progress-track"><span style="width:${c.orders/max*100}%"></span></div></div>`).join('')}</div><div class="panel-note">${cities[0]?`Kota <strong>${escape(cities[0].name)}</strong> mencatat volume tertinggi dengan ${n(cities[0].orders)} pesanan (${decimal(cities[0].orders/all*100)}%).`:'Distribusi kota.'}</div></section>`;}
function shippingPanel(){const ships=(state.result.shipping||[]).filter(s=>s.name&&s.name!=='Tidak diketahui'),all=state.result.summary.orders||1,max=ships[0]?.orders||1;if(!ships.length)return '';return `<section class="panel">${head('Distribusi Kurir & Ekspedisi','Layanan logistik dan pengiriman pesanan',`<span class="chip">${ships.length} KURIR</span>`)}<div class="panel-body bars">${ships.slice(0,6).map(s=>`<div class="bar-item"><div class="bar-head"><span><strong>${escape(s.name)}</strong> (${decimal(s.orders/all*100)}%)</span><b>${n(s.orders)} <small>pesanan · ${money(s.revenue||0,true)}</small></b></div><div class="progress-track"><span style="width:${s.orders/max*100}%"></span></div></div>`).join('')}</div><div class="panel-note">${ships[0]?`Ekspedisi <strong>${escape(ships[0].name)}</strong> mendominasi ${decimal(ships[0].orders/all*100)}% pengiriman pesanan.`:'Data pengiriman.'}</div></section>`;}
function trends(){const hasGeoShip=citiesPanel()||shippingPanel(),hasTimePay=paymentsPanel()||hourlyPanel()||dayOfWeekPanel();return title('Tren penjualan','Dari pola bulanan, Pareto 80/20, hari belanja, kota, kurir, hingga asosiasi keranjang belanja.',button('Ekspor ringkasan','export-json','','download'))+banner()+(state.result?filters()+stats()+`<div class="section-gap">${trendPanel()}</div>${paretoPanel()}<div class="grid-halves">${productsPanel(10)}${regionsPanel()}</div>${hasGeoShip?`<div class="grid-halves section-gap">${citiesPanel()}${shippingPanel()}</div>`:''}${hasTimePay?`<div class="grid-halves section-gap">${dayOfWeekPanel()}${hourlyPanel()}</div>`:''}${paymentsPanel()?`<div class="section-gap">${paymentsPanel()}</div>`:''}${basketPanel()}<section class="panel section-gap">${head('Detail periode bulanan','Pesanan unik per bulan · jumlah bulanan dapat berbeda dari pesanan unik lintas periode.')}<div class="table-wrap"><table><thead><tr><th>Bulan</th><th class="numeric">Nilai penjualan</th><th class="numeric">Pesanan</th><th class="numeric">Unit</th></tr></thead><tbody>${state.result.monthly.map(m=>`<tr><td>${escape(monthLabel(m.month))}</td><td class="numeric">${money(m.revenue)}</td><td class="numeric">${n(m.orders)}</td><td class="numeric">${n(m.units)}</td></tr>`).join('')}</tbody></table></div></section>`:noResult());}
function scatter(){const seg=state.result.segmentation;if(!seg.k)return empty(seg.message);const all=seg.customers,points=all.filter((_,i)=>i%Math.max(1,Math.ceil(all.length/700))===0),w=660,h=290,L=61,R=20,T=20,B=43,maxX=Math.max(...all.map(c=>c.recency))||1,maxY=Math.log1p(Math.max(...all.map(c=>c.monetary)))||1;
 return `<svg viewBox="0 0 ${w} ${h}" class="chart" role="img" aria-label="Scatter Recency versus Monetary logaritmik, maksimum 700 pelanggan"><title>Recency (hari) versus Monetary (sumbu log1p). Frequency tetap menjadi fitur clustering.</title>${[0,.25,.5,.75,1].map(f=>`<line class="gridline" x1="${L}" y1="${T+(h-T-B)*(1-f)}" x2="${w-R}" y2="${T+(h-T-B)*(1-f)}"/><text x="${L-8}" y="${T+(h-T-B)*(1-f)+4}" text-anchor="end">${escape(money(Math.expm1(maxY*f),true))}</text><text x="${L+(w-L-R)*f}" y="${h-B+20}" text-anchor="middle">${n(maxX*f)}</text>`).join('')}${points.map(c=>`<circle cx="${L+c.recency/maxX*(w-L-R)}" cy="${T+(1-Math.log1p(c.monetary)/maxY)*(h-T-B)}" r="3.3" fill="${palette[c.cluster]}" opacity=".7"><title>${escape(c.id)} · Cluster ${c.cluster+1} · R ${c.recency} · F ${c.frequency} · M ${money(c.monetary)}</title></circle>`).join('')}<text class="axis-label" x="${w/2}" y="${h-3}" text-anchor="middle">Recency (hari sejak pembelian terakhir)</text></svg>`;
}
function segments(){if(!state.result)return title('Segmentasi pelanggan','Pahami pelanggan melalui perilaku pembelian.')+noResult();const seg=state.result.segmentation;
 return title('Segmentasi pelanggan','RFM mengubah transaksi menjadi profil. K-Means menemukan kemiripannya.',button('Ekspor pelanggan RFM','export-rfm','','download'))+banner()+filters()+`<form class="filters" id="cluster-form"><span class="filter-label">${icon('users')} Pengaturan clustering</span><label>Jumlah cluster<select name="k"><option value="auto" ${state.k==='auto'?'selected':''}>Otomatis · silhouette tertinggi</option>${Array.from({length:7},(_,i)=>i+2).map(k=>`<option value="${k}" ${String(state.k)===String(k)?'selected':''}>${k} cluster</option>`).join('')}</select></label><button class="button primary" type="submit">Hitung ulang ${icon('refresh')}</button></form>${seg.k?`<div class="metric-inline"><div>Cluster terpilih<b>${seg.k}</b></div><div>Saran silhouette<b>k = ${seg.recommended}</b></div><div>Total Estimasi CLV<b>${money(seg.totalCLV||0,true)}</b></div><div>Rerata Risiko Churn<b>${seg.avgChurn||0}%</b></div><div>Silhouette sampel<b>${seg.silhouette===null?'—':decimal(seg.silhouette)}</b></div></div><div class="cluster-cards">${seg.clusters.map((c,i)=>`<article class="cluster-card" style="--accent:${palette[i]}"><h3>${c.name}<span>${n(c.count)} pelanggan</span></h3><div style="margin:8px 0 10px;display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap"><span class="chip" style="background:${palette[i]}18;color:${palette[i]};border-color:${palette[i]}35">${escape(c.persona||'Profil Pelanggan')}</span><button type="button" class="button small subtle" data-action="filter-cluster" data-cluster="${i}" style="height:26px;padding:0 10px;font-size:11px">${String(state.clusterFilter)===String(i)?'✓ Difilter':'Lihat pelanggan →'}</button></div><dl><dt>Recency rata-rata</dt><dd>${decimal(c.recency)} hari</dd><dt>Frequency rata-rata</dt><dd>${decimal(c.frequency)} ×</dd><dt>Monetary rata-rata</dt><dd>${money(c.monetary,true)}</dd><dt>Estimasi CLV / Pelanggan</dt><dd><strong>${money(c.avgCLV||0,true)}</strong></dd><dt>Tingkat Risiko Churn</dt><dd><span class="chip ${c.avgChurn>=70?'red':c.avgChurn>=40?'amber':'green'}">${c.avgChurn}% churn (${c.highChurnPct}% high risk)</span></dd></dl><div class="cluster-strategy"><strong>Rekomendasi Aksi:</strong> ${escape(c.strategy||'Tingkatkan interaksi belanja')}</div></article>`).join('')}</div><div class="grid-halves"><section class="panel">${head('Peta pelanggan','Recency × Monetary · sumbu Monetary log1p')}<div class="panel-body">${scatter()}<div class="legend">${seg.clusters.map((c,i)=>`<span><i style="background:${palette[i]}"></i>${c.name}</span>`).join('')}</div></div><div class="panel-note">Maksimal 700 titik ditampilkan. Clustering memakai seluruh pelanggan dan ketiga variabel RFM.</div></section><section class="panel">${head('Evaluasi jumlah cluster','Elbow melalui inertia; silhouette sebagai rekomendasi otomatis.')}<div class="panel-body">${chart(seg.evaluation,'inertia','Inertia untuk setiap nilai k',v=>decimal(v),'elbow')}</div><div class="panel-note">K-Means++ · 5 inisialisasi · seed 42 · maksimum 100 iterasi per inisialisasi.</div></section></div><section class="panel section-gap">${head('Perbandingan model','Silhouette dihitung pada sampel deterministik maksimum 500 pelanggan.')}<div class="table-wrap"><table><thead><tr><th>Jumlah cluster</th><th class="numeric">Inertia</th><th class="numeric">Silhouette</th><th>Keputusan</th></tr></thead><tbody>${seg.evaluation.map(e=>`<tr><td>k = ${e.k}</td><td class="numeric">${decimal(e.inertia)}</td><td class="numeric">${e.silhouette===null?'Tidak terdefinisi':decimal(e.silhouette)}</td><td>${e.k===seg.k?'<span class="chip">AKTIF</span> ':''}${e.k===seg.recommended?'<span class="chip blue">SARAN</span>':''}</td></tr>`).join('')}</tbody></table></div></section>${customerTable()}<div class="notice warning" style="margin-top:20px">Nomor cluster diurutkan berdasarkan rerata Monetary, bukan label kualitas pelanggan. Saran k dari silhouette perlu dinilai bersama ukuran cluster, stabilitas, dan konteks bisnis. Pergantian filter menghitung ulang RFM, referensi tanggal, scaler, dan cluster.</div>`:`<div class="panel section-gap empty-hero"><div class="empty-hero-icon">${icon('users')}</div><h3>Mode Segmentasi Pelanggan (RFM + K-Means)</h3><p>${escape(seg.message||'Dataset aktif tidak menyediakan kolom ID pelanggan langsung.')}<br>Dataset <strong>${escape(state.source)}</strong> mencatat transaksi tingkat pesanan (order-level). Aktifkan <strong>Simulasi ID Pelanggan (Proxy RFM)</strong> untuk mendemonstrasikan K-Means, Persona Pelanggan, dan Prediksi CLV pada data ini.</p><div class="button-group" style="justify-content:center"><button class="button primary" data-action="enable-proxy-rfm">${icon('spark')} Aktifkan ID Pelanggan Simulasi &amp; Hitung K-Means</button><button class="button subtle" data-action="demo">${icon('refresh')} Gunakan Dataset Demo</button></div></div>`}`;
}
function customerTable(){const seg=state.result.segmentation,search=state.search.toLowerCase(),sorters={'monetary-desc':(a,b)=>b.monetary-a.monetary,'clv-desc':(a,b)=>(b.clv||0)-(a.clv||0),'frequency-desc':(a,b)=>b.frequency-a.frequency,'churn-desc':(a,b)=>(b.churnProb||0)-(a.churnProb||0),'recency-asc':(a,b)=>a.recency-b.recency},list=seg.customers.filter(c=>c.id.toLowerCase().includes(search)&&(state.clusterFilter==='all'||String(c.cluster)===String(state.clusterFilter))&&(state.churnFilter==='all'||c.churnRisk===state.churnFilter)).slice().sort(sorters[state.customerSort]||sorters['monetary-desc']),pages=Math.max(1,Math.ceil(list.length/12));state.customerPage=Math.min(state.customerPage,pages-1);const begin=state.customerPage*12;
 const searchInput='<div class="button-group" style="gap:8px"><select id="customer-cluster-filter" aria-label="Filter cluster" style="height:36px;min-width:140px"><option value="all">Semua cluster</option>'+seg.clusters.map((cl,idx)=>'<option value="'+idx+'" '+(String(state.clusterFilter)===String(idx)?'selected':'')+'>'+escape(cl.name)+' ('+escape(cl.persona)+')</option>').join('')+'</select><select id="customer-churn-filter" aria-label="Filter risiko churn" style="height:36px;min-width:135px"><option value="all">Semua risiko churn</option>'+['Tinggi','Sedang','Rendah'].map(rk=>'<option value="'+rk+'" '+(state.churnFilter===rk?'selected':'')+'>Risiko '+rk+'</option>').join('')+'</select><select id="customer-sort" aria-label="Urutkan pelanggan" style="height:36px;min-width:155px">'+[['monetary-desc','Monetary tertinggi'],['clv-desc','Estimasi CLV tertinggi'],['frequency-desc','Frequency tertinggi'],['churn-desc','Risiko Churn tertinggi'],['recency-asc','Recency terbaru']].map(([k,lbl])=>'<option value="'+k+'" '+(state.customerSort===k?'selected':'')+'>Urut: '+lbl+'</option>').join('')+'</select><input class="search-input" id="customer-search" type="search" placeholder="Cari ID pelanggan…" aria-label="Cari ID pelanggan" value="'+escape(state.search)+'"></div>';
 const rows=list.slice(begin,begin+12).map(c=>'<tr><td><strong>'+escape(c.id)+'</strong></td><td class="numeric">'+n(c.recency)+' hari</td><td class="numeric">'+n(c.frequency)+'×</td><td class="numeric">'+money(c.monetary)+'</td><td><span class="chip '+(c.churnRisk==='Tinggi'?'red':c.churnRisk==='Sedang'?'amber':'green')+'">'+c.churnRisk+' ('+c.churnProb+'%)</span></td><td class="numeric"><strong>'+money(c.clv||0)+'</strong></td><td><span class="chip" style="background:'+palette[c.cluster]+'18;color:'+palette[c.cluster]+';border-color:'+palette[c.cluster]+'35">Cluster '+(c.cluster+1)+(c.persona?' · '+escape(c.persona):'')+'</span></td></tr>').join('')||'<tr><td colspan="7">Tidak ada pelanggan yang cocok dengan filter ini.</td></tr>';
 return '<section class="panel" id="customer-panel">'+head('Detail pelanggan RFM, Churn & CLV',n(list.length)+' pelanggan · nilai asli & skor analitik',searchInput)+'<div class="table-wrap"><table><thead><tr><th>ID pelanggan</th><th class="numeric">Recency</th><th class="numeric">Frequency</th><th class="numeric">Monetary</th><th>Risiko Churn</th><th class="numeric">Estimasi CLV</th><th>Cluster</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="pagination"><span>Halaman '+(state.customerPage+1)+' dari '+pages+'</span><div class="button-group"><button class="button small" data-action="prev-customers" '+(state.customerPage===0?'disabled':'')+'>Sebelumnya</button><button class="button small" data-action="next-customers" '+(state.customerPage>=pages-1?'disabled':'')+'>Berikutnya</button></div></div></section>';
}
function backlogView(){let index=0;const done=Object.values(state.backlog).filter(s=>s==='done').length;
 const header=title('Backlog proyek','25 pekerjaan, satu alur penelitian. Tandai centang langsung atau gunakan tombol otomatis.',button('Tandai otomatis progres','auto-backlog','primary small','check')+button('Ekspor status backlog','export-backlog','small','download')+button('Reset','reset-backlog','subtle small'));
 const notice='<div class="notice">Perbarui status tugas secara manual, centang langsung, atau klik <strong>Tandai otomatis progres</strong> untuk mengisi tugas yang sudah diselesaikan sistem. Perubahan tersimpan di browser ini.</div>';
 const metrics='<div class="metric-inline"><div>Semua backlog<b>25</b></div><div>Ditandai selesai<b>'+done+'</b></div><div>Progres kelompok<b>'+n(done/25*100)+'%</b></div></div>';
 const sections=backlog.map(([stage,items],i)=>{
  const titleHtml='<span class="backlog-title"><span>0'+(i+1)+'</span>'+stage+'</span>';
  const itemsHtml=items.map(([label,desc])=>{
   const id=++index;const isDone=state.backlog[id]==='done';
   const options=[['','Belum ditandai'],['todo','To do'],['doing','In progress'],['done','Done']].map(([key,value])=>'<option value="'+key+'" '+(state.backlog[id]===key?'selected':'')+'>'+value+'</option>').join('');
   return '<div class="backlog-item '+(isDone?'is-done':'')+'"><span class="number">'+String(id).padStart(2,'0')+'</span><label class="backlog-check" title="Centang selesai"><input type="checkbox" data-backlog-toggle="'+id+'" '+(isDone?'checked':'')+' aria-label="Centang selesai tugas '+id+'"></label><div><strong>'+label+'</strong><small>'+desc+'</small></div><select data-backlog="'+id+'" aria-label="Status backlog '+id+'">'+options+'</select></div>';
  }).join('');
  return '<section class="panel">'+head(titleHtml,items.length+' backlog')+itemsHtml+'</section>';
 }).join('');
 return header+notice+metrics+'<div class="backlog-grid">'+sections+'</div>';
}
function method(){const s=state.result?.summary,seg=state.result?.segmentation;
 return title('Metodologi & laporan','Aturan yang transparan membuat hasil analisis bisa dijelaskan.',button('Cetak / simpan PDF','print','','download')+button('Ekspor laporan JSON','export-json','','download'))+banner()+`<div class="grid-main"><section class="panel">${head('Alur analisis','Dari transaksi mentah menuju kelompok pelanggan')}<div class="panel-body method-steps">${[
 ['01 · Data & konteks','Dataset final masih perlu ditetapkan. Fokus Indonesia membutuhkan sumber transaksi Indonesia yang benar; penggantian nama negara atau simbol mata uang tidak mengubah asal dataset.'],
 ['02 · Cleaning','Duplikat identik opsional → pembatalan/retur → status belum final → data tidak valid. Tanggal, ID pesanan, produk, kuantitas, dan harga wajib valid. Status tidak dipetakan berarti transaksi diasumsikan final.'],
 ['03 · Tren penjualan',applied?.options.valueMode==='order'?'Mode pesanan: jumlahkan total pembayaran sumber secara langsung pada satu baris per pesanan. Diskon/ongkir mengikuti definisi sumber. Analisis produk individual tidak tersedia.':'Jumlah pesanan = ID pesanan unik. Produk terlaris = total kuantitas. Wilayah teratas = jumlah ID pesanan unik per wilayah. Nilai penjualan = jumlah quantity × unit price pada pembelian positif.'],
 ['04 · Fitur RFM','Recency = tanggal referensi − pembelian terakhir (hari). Frequency = ID pesanan unik per pelanggan. Monetary = total pembelian positif per pelanggan. Tanggal referensi = tanggal maksimum dalam cakupan + 1 hari.'],
 ['05 · Transformasi & clustering','RFM → log1p → standardisasi z-score (simpangan baku populasi) → K-Means++. K 2–8, dibatasi jumlah pelanggan dan profil unik; lima inisialisasi, seed 42, maksimal 100 iterasi. Model dengan inertia terkecil dipilih untuk setiap k.'],
 ['06 · Evaluasi & interpretasi','Otomatis memilih silhouette tertinggi yang valid. Silhouette menggunakan jarak Euclidean pada sampel deterministik maksimum 500 pelanggan. Inertia dihitung untuk seluruh pelanggan. Nama bisnis segmen perlu disusun berdasarkan rerata RFM, bukan nomor cluster.']
 ].map(([title,desc])=>`<article class="method-step"><h3>${title}</h3><p>${desc}</p></article>`).join('')}</div></section><div><section class="panel section-gap">${head('Kesimpulan sementara','Disusun dari hasil aktif; periksa sebelum menjadi laporan akhir.')}<div class="panel-body prose">${s?`<p>Sumber: <strong>${escape(state.source)}</strong>. ${state.demo?'Data sintetis untuk pengujian sistem.':''}</p><p>Dalam periode ${date(s.start)} hingga ${date(s.end)}, terdapat <strong>${n(s.orders)} pesanan unik</strong> dengan nilai pembelian ${money(s.revenue)} dan ${n(s.customers)} pelanggan teridentifikasi.</p><p>${state.result.products[0]?'Produk dengan unit tertinggi: '+escape(state.result.products[0].name)+' ('+n(state.result.products[0].quantity)+' unit).':'Tidak ada produk dalam filter.'}</p><p>${seg.k?'K-Means menghasilkan '+seg.k+' cluster. Tanggal referensi RFM: '+date(s.reference)+'.':'Segmentasi belum dapat dilakukan.'}</p>`:'<p>Jalankan analisis untuk menyusun ringkasan otomatis.</p>'}</div></section><section class="panel section-gap">${head('Batasan implementasi','Status teknologi yang sudah berjalan')}<div class="panel-body prose"><p>MVP ini memakai HTML, CSS, JavaScript, Web Worker, dan SheetJS untuk Excel. Perhitungan berjalan di satu browser; data tidak dikirim ke backend.</p><p><strong>Belum menggunakan Spark/Hadoop atau komputasi terdistribusi.</strong> Batas unggah 120 MB merupakan pembatas aplikasi, bukan jaminan semua file sebesar itu dapat diproses. Kapasitas bergantung memori perangkat dan ukuran workbook setelah dibuka.</p><p>Untuk tuntutan Big Data, gunakan tahap lanjutan Python + PySpark + Parquet untuk cleaning/agregasi, Spark ML untuk clustering, API untuk hasil, lalu dashboard ini sebagai antarmuka. Perlu pengujian kinerja dan integrasi tersendiri.</p><p>Dataset multi-tabel harus di-JOIN terlebih dahulu. Harga harus satu mata uang. Pembelian sebelum diskon bukan total pembayaran bersih. Sistem tidak mengubah produk, kota, atau pesanan menjadi identitas pelanggan.</p></div></section><section class="panel">${head('Referensi','Sumber metodologi dan dataset')}<div class="panel-body prose"><p><a href="https://scikit-learn.org/stable/modules/generated/sklearn.cluster.KMeans.html" target="_blank" rel="noopener noreferrer">Dokumentasi K-Means ↗</a></p><p><a href="https://scikit-learn.org/stable/modules/generated/sklearn.metrics.silhouette_score.html" target="_blank" rel="noopener noreferrer">Definisi silhouette ↗</a></p><p>Implementasi algoritma dashboard ditulis dalam JavaScript; tidak menjalankan pustaka scikit-learn di browser.</p><p><a href="#dataset">Lihat kandidat dataset Indonesia →</a></p></div></section></div></div>`;
}
function executive(){
 if(!state.result)return title('Ringkasan eksekutif','Laporan komprehensif performa penjualan, segmentasi pelanggan, dan rekomendasi bisnis.',button('Cetak Laporan PDF / Slide','print','primary','download'))+noResult();
 const s=state.result.summary,seg=state.result.segmentation,c=state.result.cleaning,ba=state.result.basketAnalysis;
 const topCat=state.result.categories[0],topPay=state.result.payments[0],topCluster=seg.clusters[0];
 const peakHour=state.result.hourly?.slice().sort((a,b)=>b.orders-a.orders)[0],peakDay=state.result.dayOfWeek?.slice().sort((a,b)=>b.orders-a.orders)[0],topCity=(state.result.cities||[]).find(x=>x.name&&x.name!=='Tidak diketahui'),topShip=(state.result.shipping||[]).find(x=>x.name&&x.name!=='Tidak diketahui'),par=state.result.pareto;
 return title('Ringkasan eksekutif','Laporan performa penjualan, segmentasi pelanggan, dan rekomendasi bisnis strategis.',button('Cetak Laporan PDF / Slide','print','primary','download'))+banner()+`<div class="executive-sheet"><div class="stats">${[
  ['Total Omzet Bersih',money(s.revenue,true),'money','Penjualan valid yang lolos cleaning','Omzet Valid'],
  ['Total Transaksi',n(s.orders)+' pesanan','bag',n(s.units)+' unit barang terjual','Volume Order'],
  ['Portofolio Pelanggan',n(s.customers)+' pembeli','users',seg.k?`Total Est. CLV: ${money(seg.totalCLV||0,true)}`:'RFM nonaktif','Total Buyer'],
  ['Audit Data Cleaning',decimal(c.raw?c.valid/c.raw*100:0)+'% valid','clean',n(c.valid)+' dari '+n(c.raw)+' baris mentah','Akurasi Pipeline']
 ].map(([label,val,ic,foot,tag])=>`<article class="stat"><div class="stat-head"><span class="stat-tag">${tag}</span><span class="stat-icon">${icon(ic)}</span></div><div class="stat-value">${val}</div><div class="stat-label">${label}</div><div class="stat-foot">${foot}</div></article>`).join('')}</div><div class="grid-halves section-gap"><section class="panel">${head('Temuan operasional retail','Waktu belanja, logistik, kota, pembayaran & kategori utama')}<div class="panel-body prose"><p>Performa periode <strong>${date(s.start)}</strong> hingga <strong>${date(s.end)}</strong> membukukan rerata nilai belanja per pesanan (AOV) sebesar <strong>${money(s.aov,true)}</strong>.</p><div class="metric-inline"><div>Kategori Teratas<b>${escape(topCat?.name||'—')}</b></div><div>Metode Bayar<b>${escape(topPay?.name||'—')}</b></div><div>Hari &amp; Jam Sibuk<b>${peakDay?peakDay.name:'—'} · ${peakHour?peakHour.label:'—'}</b></div><div>Kota &amp; Kurir Utama<b>${escape(topCity?.name||'—')} · ${escape(topShip?.name||'—')}</b></div></div><p style="margin-top:12px">Aktivitas transaksi memuncak pada hari <strong>${escape(peakDay?.name||'tertentu')}</strong> pukul <strong>${peakHour?peakHour.label:'jam tertentu'}</strong> dengan metode pembayaran <strong>${escape(topPay?.name||'standar')}</strong> dan ekspedisi <strong>${escape(topShip?.name||'utama')}</strong>. Operasional pergudangan dan promosi kilat disarankan difokuskan pada periode ini.</p></div></section><section class="panel">${head('Profil pelanggan, Pareto 80/20 & risiko churn','Segmentasi K-Means, retensi pembeli berulang & prediksi CLV')}<div class="panel-body prose"><p>${seg.k?`Populasi terbagi ke dalam <strong>${seg.k} kelompok pelanggan</strong> dengan skor Silhouette <strong>${decimal(seg.silhouette)}</strong>. Rerata risiko churn portofolio berada di angka <strong>${seg.avgChurn}%</strong>.`:'Segmentasi RFM belum aktif.'}</p>${par?`<div class="metric-inline"><div>Repeat Buyer Rate<b>${decimal(par.repeatRatePct)}% (${n(par.repeatCustomers)} pembeli)</b></div><div>Omzet Repeat Buyer<b>${decimal(par.repeatRevenueSharePct)}%</b></div><div>Pareto 20% Pembeli<b>${decimal(par.top20CustomerSharePct)}% omzet</b></div></div>`:''}${topCluster?`<div class="insight">${icon('spark')}<span>Segmen utama <strong>${topCluster.name} (${escape(topCluster.persona)})</strong> menyumbang kontribusi terbesar (${money(topCluster.monetary,true)} / pelanggan) dengan estimasi Customer Lifetime Value <strong>${money(topCluster.avgCLV,true)}</strong>.</span></div>`:''}<p style="margin-top:10px">Terdapat ${seg.clusters?.filter(cl=>cl.avgChurn>=50).length||0} cluster pelanggan yang memerlukan intervensi retensi aktif sebelum beralih ke platform kompetitor.</p></div></section></div>${ba?.rules.length?`<section class="panel section-gap">${head('Peluang bundling produk (Market Basket Analysis)','Rekomendasi cross-selling dengan tingkat afinitas belanja tertinggi')}<div class="table-wrap"><table><thead><tr><th>Kategori Utama</th><th>Kategori Asosiasi</th><th class="numeric">Peluang Beli</th><th class="numeric">Kekuatan Asosiasi (Lift)</th><th>Rekomendasi Bisnis</th></tr></thead><tbody>${ba.rules.slice(0,3).map(r=>`<tr><td><strong>${escape(r.antecedent)}</strong></td><td><strong>${escape(r.consequent)}</strong></td><td class="numeric"><strong>${decimal(r.confidence*100)}%</strong></td><td class="numeric"><span class="chip green">Lift ${decimal(r.lift)}×</span></td><td>${escape(r.strategy)}</td></tr>`).join('')}</tbody></table></div></section>`:''}<section class="panel section-gap">${head('Rencana aksi strategis 30 — 60 — 90 hari','Panduan implementasi nyata bagi tim manajemen retail')}<div class="panel-body"><div class="method-steps">${[
  ['30 Hari Pertama · Retensi Pelanggan At-Risk','Luncurkan kampanye re-aktivasi berbasis WhatsApp/Email dengan kupon penahan khusus bagi kelompok pelanggan dengan risiko churn tinggi.'],
  ['60 Hari Berikutnya · Optimasi Bundling Keranjang','Terapkan paket bundling dan diskon otomatis untuk pasangan kategori dengan Lift > 1.2× untuk meningkatkan basket size dan AOV.'],
  ['90 Hari Ke Depan · Program Loyalitas VIP','Kembangkan program keanggotaan eksklusif bagi segmen Champions dengan akses awal produk baru dan layanan prioritas.']
 ].map(([title,desc])=>`<article class="method-step"><h3>${title}</h3><p>${desc}</p></article>`).join('')}</div></div></section></div>`;
}
function architecture(){
 return title('Arsitektur Big Data','Desain pipeline pemrosesan data berskala besar dengan Apache Spark (PySpark).',button('Ekspor skrip PySpark','download-spark','primary','download'))+`<div class="grid-main"><section class="panel">${head('Alur pipeline komputasi terdistribusi','End-to-end Big Data Architecture untuk transaksi retail')}<div class="panel-body"><div class="method-steps">${[
  ['01 · Ingestion & Raw Data Lake','File transaksi mentah (CSV/JSON/Parquet) dikumpulkan ke distributed storage seperti HDFS, Amazon S3, atau GCS dengan partisi bulanan.'],
  ['02 · Distributed Data Cleaning','Apache Spark (PySpark DataFrame API) membersihkan jutaan baris: deduplikasi paralel, filter retur/batal, dan rekonsiliasi data.'],
  ['03 · Rekayasa Fitur RFM','Fungsi Window Spark menghitung Recency (datediff), Frequency (countDistinct), dan Monetary (sum) untuk seluruh populasi pelanggan.'],
  ['04 · Spark MLlib K-Means','Transformasi log1p, VectorAssembler, dan StandardScaler terdistribusi. KMeans (k-means||) dievaluasi dengan ClusteringEvaluator (Silhouette Score).'],
  ['05 · Presentation Layer (RetailScope)','Hasil agregasi diekspor ke Parquet / JSON lalu divisualisasikan secara interaktif dan responsif di dashboard RetailScope.']
 ].map(([t,d])=>`<article class="method-step"><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></div></section><div><section class="panel section-gap">${head('Perbandingan komputasi','Skalabilitas browser vs cluster Spark')}<div class="panel-body prose"><table style="margin-top:5px"><thead><tr><th>Dimensi</th><th>Web Worker MVP</th><th>Apache Spark</th></tr></thead><tbody><tr><td>Node</td><td>1 Browser lokal</td><td>Multi-node Cluster</td></tr><tr><td>Kapasitas</td><td>Hingga ~500.000 baris</td><td>Ratusan juta / Miliar</td></tr><tr><td>Algoritma</td><td>JS K-Means++</td><td>Spark MLlib k-means||</td></tr><tr><td>Penyimpanan</td><td>In-Memory RAM</td><td>HDFS / Parquet Lake</td></tr><tr><td>Peran</td><td>Eksplorasi & Visualisasi</td><td>Heavy ETL & Batch ML</td></tr></tbody></table></div></section><section class="panel">${head('Skrip PySpark resmi','File pendamping: pyspark_pipeline.py')}<div class="panel-body prose"><p>Skrip komputasi terdistribusi PySpark resmi disertakan di repositori proyek: <code>pyspark_pipeline.py</code>.</p><p>Skrip siap dijalankan di Google Colab, Databricks, atau terminal kampus:</p><p><code>python pyspark_pipeline.py</code></p><button class="button primary small" data-action="download-spark">${icon('download')} Unduh pyspark_pipeline.py</button></div></section></div></div>`;
}
async function analyze({filters=state.filters,k=state.k,mapping=state.mapping,options=state.options,currency=state.currency}={}){
 const previousPage=state.page;state.busy=true;state.error='';state.progress='Menyiapkan analisis…';render();
 try{const result=await call('analyze',{mapping,options,filters,k});state.result=result;state.mapping=mapping;state.options=options;state.filters=filters;state.k=k;state.currency=currency;applied={mapping:{...mapping},options:{...options},filters:{...filters},k,currency,source:state.source,demo:state.demo};state.dirty=false;state.customerPage=0;state.search='';state.clusterFilter='all';state.churnFilter='all';if(!state.demo){try{localStorage.setItem('retailscope-session',JSON.stringify({source:state.source,mapping,options,filters,k,currency,analyzed:true}));}catch{}}}
 catch(e){state.error=e.message;state.page=previousPage;}
 finally{state.busy=false;render();}
}
async function loadDemo(){try{localStorage.removeItem('retailscope-session');}catch{}state.busy=true;state.error='';state.progress='Menyiapkan transaksi demo Indonesia…';render();try{const meta=await call('demo');state.meta=meta;state.mapping=meta.mapping;state.source='Demo retail Indonesia · Jan–Nov 2025';state.demo=true;state.result=null;applied=null;state.filters={start:'',end:'',region:''};state.k='auto';state.currency='IDR';state.options={dedupe:true,invoiceCancellation:false,dateOrder:'dmy',numberFormat:'plain'};await analyze();}catch(e){state.error=e.message;state.busy=false;render();}}
async function importFile(file){if(!file)return;state.busy=true;state.progress='Membaca '+file.name+'…';state.error='';render();try{const meta=await call('import',{file});state.meta=meta;state.mapping=meta.mapping;state.options={dedupe:true,invoiceCancellation:false,dateOrder:'dmy',numberFormat:'plain',valueMode:meta.mapping.amount&&!meta.mapping.price?'order':'item',proxyCustomer:!meta.mapping.customer};state.source=file.name;state.demo=false;state.result=null;applied=null;state.page='dataset';state.filters={start:'',end:'',region:'',city:''};state.k='auto';state.dirty=false;try{localStorage.setItem('retailscope-session',JSON.stringify({source:state.source,mapping:state.mapping,options:state.options,filters:state.filters,k:state.k,currency:state.currency,analyzed:false}));}catch{}location.hash='dataset';toast('Unggah berhasil. Lanjutkan dengan tombol Jalankan analisis di bawah pemetaan kolom.');}catch(e){state.error=e.message;}finally{state.busy=false;render();if(!state.error)$('#mapping-form')?.scrollIntoView({behavior:'smooth',block:'start'});}}
function download(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function csv(rows){if(!rows.length)throw Error('Tidak ada data untuk diekspor.');const keys=Object.keys(rows[0]),cell=v=>{let s=String(v??'');if(/^[=+@\t\r]/.test(s)||(/^\-/.test(s)&&!Number.isFinite(Number(s))))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};return '\uFEFF'+[keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n');}
function report(){if(!state.result)throw Error('Jalankan analisis terlebih dahulu.');const {preview,rfm,...rest}=state.result;return {project:'Analisis Tren Penjualan dan Segmentasi Pelanggan Berdasarkan Data Transaksi Retail Indonesia',generatedAt:new Date().toISOString(),mode:state.demo?'synthetic-demo':'user-file',source:state.source,implementation:'Single-browser Web Worker MVP; no distributed processing',settings:applied,definitions:{sales:applied.options.valueMode==='order'?'Sum of positive source order payments, one row per order; discounts/shipping follow source definition':'Positive purchases; sum(quantity * unit price), before discounts/shipping; returns excluded',frequency:'Distinct invoice IDs per customer',reference:'Maximum transaction date within active filters + 1 day',preprocessing:'log1p RFM then population standardization',silhouette:'Pairwise Euclidean distances within deterministic sample of up to 500 customers'},result:rest};}
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(nav.some(n=>n[0]===page)){state.page=page;state.menu=false;state.error='';render();window.scrollTo(0,0);}});
$('#app').addEventListener('submit',async e=>{e.preventDefault();if(state.busy)return;const form=e.target,data=new FormData(form);
 if(form.id==='mapping-form'){
  const mapping=Object.fromEntries(fields.map(([key])=>[key,data.get('map-'+key)||'']));
  const orderMode=data.get('valueMode')==='order';const required=orderMode?['invoice','date','quantity','amount']:['invoice','date','quantity','price'];const missing=required.filter(key=>!mapping[key]);
  if(missing.length||(!orderMode&&!mapping.product&&!mapping.description)){state.error='Analisis belum dimulai. Lengkapi kolom: '+missing.map(key=>fields.find(f=>f[0]===key)[1]).concat(!orderMode&&!mapping.product&&!mapping.description?['ID atau nama produk']:[]).join(', ')+'.';render();document.querySelector('.notice.error')?.scrollIntoView({behavior:'smooth',block:'center'});return;}
  const chosen=Object.values(mapping).filter(Boolean);if(new Set(chosen).size!==chosen.length){toast('Satu kolom tidak boleh dipakai untuk dua peran. Periksa pemetaan.');return;}
  await analyze({mapping,options:{valueMode:data.get('valueMode'),dateOrder:data.get('dateOrder'),numberFormat:data.get('numberFormat'),dedupe:data.has('dedupe'),invoiceCancellation:data.has('invoiceCancellation'),proxyCustomer:data.has('proxyCustomer')},currency:data.get('currency')});if(!state.error){state.page='overview';location.hash='overview';render();toast('Analisis selesai. Hasil sudah dihitung dari dataset aktif.');}
 } else if(form.id==='filters-form'){const filters=Object.fromEntries(['start','end','region','city'].map(k=>[k,data.get(k)]));await analyze({filters,k:'auto'});}
 else if(form.id==='cluster-form')await analyze({k:data.get('k')});
});
$('#app').addEventListener('change',e=>{const el=e.target;if(el.id==='file')importFile(el.files[0]);if(el.id==='customer-cluster-filter'){state.clusterFilter=el.value;state.customerPage=0;render();}if(el.id==='customer-churn-filter'){state.churnFilter=el.value;state.customerPage=0;$('#customer-panel').outerHTML=customerTable();}if(el.id==='customer-sort'){state.customerSort=el.value;state.customerPage=0;$('#customer-panel').outerHTML=customerTable();}if(el.id==='value-mode'){const form=$('#mapping-form');state.mapping=Object.fromEntries(fields.map(([key])=>[key,new FormData(form).get('map-'+key)||state.mapping[key]||'']));state.options.valueMode=el.value;render();$('#mapping-form').scrollIntoView({block:'start'});}if(el.dataset.backlogToggle){state.backlog[el.dataset.backlogToggle]=el.checked?'done':'';try{localStorage.setItem('retailscope-backlog',JSON.stringify(state.backlog));}catch{}render();}if(el.dataset.backlog){state.backlog[el.dataset.backlog]=el.value;try{localStorage.setItem('retailscope-backlog',JSON.stringify(state.backlog));}catch{toast('Browser tidak mengizinkan penyimpanan. Ekspor status backlog untuk menyimpan.');}render();}});
$('#app').addEventListener('input',e=>{if(e.target.id==='customer-search'){state.search=e.target.value;state.customerPage=0;const start=e.target.selectionStart;$('#customer-panel').outerHTML=customerTable();$('#customer-search').focus();try{$('#customer-search').setSelectionRange(start,start);}catch{}}});
$('#app').addEventListener('click',async e=>{const metric=e.target.closest('[data-metric]');if(metric){state.metric=metric.dataset.metric;render();return;}const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;
 try {
  if(action==='menu'){state.menu=!state.menu;render();}
  if(action==='toggle-theme'){state.theme=state.theme==='dark'?'light':'dark';try{localStorage.setItem('retailscope-theme',state.theme);}catch{}render();}
  if(action==='go-dataset')location.hash='dataset';
  if(action==='run-analysis'){const form=$('#mapping-form');if(form){form.requestSubmit();}else{await analyze();if(!state.error){state.page='overview';location.hash='overview';render();toast('Analisis selesai. Hasil sudah dihitung dari dataset aktif.');}else{location.hash='dataset';}}}
  if(action==='demo')await loadDemo();
  if(action==='enable-proxy-rfm'){state.options.proxyCustomer=true;await analyze({options:{...state.options,proxyCustomer:true}});render();toast('Simulasi ID pelanggan diaktifkan! K-Means dan profil persona berhasil dihitung.');}
  if(action==='reset-filters')await analyze({filters:{start:'',end:'',region:'',city:''},k:'auto'});
  if(action==='export-json')download('retailscope-laporan.json',JSON.stringify(report(),null,2));
  if(action==='filter-cluster'){const cl=el.dataset.cluster;state.clusterFilter=String(state.clusterFilter)===String(cl)?'all':cl;state.customerPage=0;render();$('#customer-panel')?.scrollIntoView({behavior:'smooth',block:'start'});}
  if(action==='export-rfm'){if(!state.result?.segmentation.k)throw Error('Belum ada hasil clustering untuk diekspor.');download('retailscope-rfm.csv',csv(state.result.segmentation.customers.map(c=>({customer_id:c.id,recency_days:c.recency,frequency_orders:c.frequency,monetary:c.monetary,currency:applied.currency,cluster:c.cluster+1,persona:c.persona||'',churn_prob_pct:c.churnProb??0,churn_risk:c.churnRisk||'',estimated_clv:Math.round(c.clv||0),reference_date:state.result.summary.reference,source:state.source,demo:state.demo}))),'text/csv;charset=utf-8');}
  if(action==='export-clean'){const rows=await call('exportClean');download('retailscope-bersih-seluruh-dataset.csv',csv(rows),'text/csv;charset=utf-8');toast('Data bersih seluruh dataset diekspor (sebelum filter dashboard).');}
  if(action==='template')download('template-retail-indonesia.csv','order_id,order_date,customer_id,product_id,product_name,quantity,unit_price,province,city,order_status\nORD-001,2025-01-15,PLG-001,P001,Kopi Arabika,2,85000,Jawa Barat,Bandung,completed\nORD-002,2025-02-20,PLG-001,P002,Tote Bag,1,45000,Jawa Barat,Bandung,completed\n','text/csv;charset=utf-8');
  if(action==='download-demo'){const response=await fetch('./demo.csv');if(!response.ok)throw Error('File demo tidak tersedia.');download('demo-sintetis-retail-indonesia.csv',await response.text(),'text/csv;charset=utf-8');}
  if(action==='auto-backlog'){const b={...state.backlog};if(state.meta){[1,2,3,4,5,6].forEach(i=>b[i]='done');}if(state.result){[7,8,9,10,11,12,13,15,16].forEach(i=>b[i]='done');if(state.result.products.length)b[14]='done';}if(state.result?.segmentation?.k){[17,18,19,20,21,22,23,24].forEach(i=>b[i]='done');}state.backlog=b;try{localStorage.setItem('retailscope-backlog',JSON.stringify(b));}catch{}render();toast('Status backlog diperbarui otomatis sesuai tahap analisis yang sudah berjalan.');}
  if(action==='reset-backlog'){state.backlog={};try{localStorage.removeItem('retailscope-backlog');}catch{}render();toast('Seluruh status backlog direset.');}
  if(action==='export-backlog'){let index=0;download('retailscope-backlog.csv',csv(backlog.flatMap(([stage,items])=>items.map(([task,notes])=>({number:++index,stage,task,notes,status:state.backlog[index]||'unmarked'})))),'text/csv;charset=utf-8');}
  if(action==='prev-customers'||action==='next-customers'){state.customerPage+=action==='next-customers'?1:-1;$('#customer-panel').outerHTML=customerTable();}
  if(action==='download-spark'){const resp=await fetch('./pyspark_pipeline.py');if(!resp.ok)throw Error('File pyspark_pipeline.py tidak ditemukan.');download('pyspark_pipeline.py',await resp.text(),'text/x-python;charset=utf-8');}
  if(action==='print')window.print();
 } catch(err){toast(err.message);}
});
['dragenter','dragover'].forEach(name=>$('#app').addEventListener(name,e=>{if(e.target.closest('#dropzone')){e.preventDefault();e.target.closest('#dropzone').classList.add('dragover');}}));
$('#app').addEventListener('dragleave',e=>e.target.closest('#dropzone')?.classList.remove('dragover'));
$('#app').addEventListener('drop',e=>{if(e.target.closest('#dropzone')){e.preventDefault();importFile(e.dataTransfer.files[0]);}});
async function initApp(){render();try{const raw=localStorage.getItem('retailscope-session');if(raw){const sess=JSON.parse(raw);if(sess&&sess.source){state.busy=true;state.progress='Memulihkan dataset sesi lokal ('+sess.source+')…';render();const meta=await call('restore');state.meta=meta;state.source=sess.source;state.demo=false;state.mapping=sess.mapping||meta.mapping;state.options=sess.options||state.options;state.filters=sess.filters||{start:'',end:'',region:'',city:''};state.k=sess.k||'auto';state.currency=sess.currency||'IDR';if(sess.analyzed!==false){await analyze({mapping:state.mapping,options:state.options,filters:state.filters,k:state.k,currency:state.currency});}else{state.busy=false;render();}return;}}}catch{try{localStorage.removeItem('retailscope-session');}catch{}}await loadDemo();}
initApp();
